import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.BbQUUm7J.js";const h=JSON.parse('{"title":"MCP tool reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/mcp-tools.md","filePath":"reference/mcp-tools.md","lastUpdated":1794936786000}'),r={name:"reference/mcp-tools.md"};function s(c,e,i,n,l,p){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="mcp-tool-reference" tabindex="-1">MCP tool reference <a class="header-anchor" href="#mcp-tool-reference" aria-label="Permalink to &quot;MCP tool reference&quot;">​</a></h1><p>Complete, source-verified inventory of both MCP servers. Audited 2026-11-17 against <code>src/mcp/server.ts</code> (TypeScript execution server) and <code>lib/mcp.js</code> (JavaScript research server). Nothing on this page is aspirational: a tool listed here is registered in the source, and its schema is the registered schema.</p><h2 id="two-surfaces-one-rule" tabindex="-1">Two surfaces, one rule <a class="header-anchor" href="#two-surfaces-one-rule" aria-label="Permalink to &quot;Two surfaces, one rule&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Server</th><th>Start with</th><th>Tools</th><th>File</th></tr></thead><tbody><tr><td>TypeScript <strong>execution</strong> server</td><td><code>furlpay mcp --wallet &lt;name&gt;</code></td><td><strong>35</strong></td><td><code>src/mcp/server.ts</code></td></tr><tr><td>JavaScript <strong>research</strong> server</td><td><code>furlpay mcp</code></td><td><strong>29</strong></td><td><code>lib/mcp.js</code></td></tr></tbody></table><p><strong>A default install cannot move funds on either surface.</strong> Every value-moving tool is structurally ABSENT from <code>tools/list</code> until the operator starts the server with <code>--enable-execution</code> AND a configured agent policy exists — execution mode refuses to start (exit 47) without one. Even in execution mode, mutating tools cannot be called directly: they require the two-phase protocol (<a href="#two-phase-execution-protocol">preview → confirm</a>). This is proven at the process level by <code>test/mcp-hardening.test.js</code> (spawn-level E2E).</p><h3 id="two-phase-execution-protocol" tabindex="-1">Two-phase execution protocol <a class="header-anchor" href="#two-phase-execution-protocol" aria-label="Permalink to &quot;Two-phase execution protocol&quot;">​</a></h3><ol><li><code>furlpay_preview_execution { tool, args }</code> — sanitizes arguments (control-char/ANSI stripping, length caps), binds them to a one-time <code>executionHash</code>, returns the net effect. Executes nothing.</li><li><code>furlpay_confirm_execution { executionHash }</code> — executes the <strong>stored</strong> arguments. Single-use, 10-minute TTL, agent-policy gate re-run on the STORED amount (a confirm call can never smuggle a bigger number past the spend caps). Attempts count against the rolling 30/min mutating rate limit even when refused; every call — allowed or refused — appends an audit line (agent, mode, tool, <strong>args hash only</strong>) to <code>~/.furlpay/mcp-audit.jsonl</code>.</li></ol><p>Direct dispatch of a mutating tool errors with <code>EXECUTION_MODE_REQUIRED</code> (read-only mode) or <code>TWO_PHASE_REQUIRED</code> (execution mode).</p><hr><h2 id="typescript-execution-server-—-35-tools" tabindex="-1">TypeScript execution server — 35 tools <a class="header-anchor" href="#typescript-execution-server-—-35-tools" aria-label="Permalink to &quot;TypeScript execution server — 35 tools&quot;">​</a></h2><h3 id="always-available-read-only" tabindex="-1">Always available (read-only) <a class="header-anchor" href="#always-available-read-only" aria-label="Permalink to &quot;Always available (read-only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Required</th><th>Optional</th><th>What it does</th><th>Status</th></tr></thead><tbody><tr><td><code>furlpay_get_hlp_yield</code></td><td>—</td><td>—</td><td>Live HLP vault equity/APY/PnL from the live <code>/info</code> response; unreported fields → <code>null</code>, never fabricated</td><td>LIVE</td></tr><tr><td><code>furlpay_balance</code></td><td>—</td><td><code>account</code></td><td>Balances across Stellar native assets, USDC, RWAs. Unauthenticated mode returns <strong>sample fixtures flagged <code>simulated: true</code></strong></td><td>SIMULATED (unauthenticated)</td></tr><tr><td><code>furlpay_get_quote</code></td><td><code>sourceAsset</code>, <code>targetAsset</code>, <code>amount</code></td><td>—</td><td>Multi-hop quotes across SDEX and Soroban AMMs</td><td>SIMULATED</td></tr><tr><td><code>furlpay_list_chains</code></td><td>—</td><td>—</td><td>Chain registry</td><td>LOCAL</td></tr><tr><td><code>furlpay_list_exchanges</code></td><td>—</td><td>—</td><td>Exchange/adapter registry</td><td>LOCAL</td></tr><tr><td><code>furlpay_market_search</code></td><td><code>query</code></td><td><code>chain</code></td><td>Market search across venues</td><td>LIVE (venue data)</td></tr><tr><td><code>furlpay_get_market_data</code></td><td><code>symbol</code></td><td>—</td><td>Mark price, funding, OI for a perpetual market</td><td>LIVE</td></tr><tr><td><code>furlpay_get_orderbook</code></td><td><code>symbol</code></td><td><code>depthLevels</code></td><td>L2 book snapshot</td><td>LIVE</td></tr><tr><td><code>furlpay_get_funding</code></td><td><code>symbol</code></td><td>—</td><td>Funding rate history</td><td>LIVE</td></tr><tr><td><code>furlpay_get_market_analysis</code></td><td><code>symbol</code></td><td>—</td><td>Microstructure analysis (OBI, micro-price)</td><td>LIVE (feed)</td></tr><tr><td><code>furlpay_compare_markets</code></td><td><code>asset</code></td><td>—</td><td>Cross-venue comparison for an asset</td><td>LIVE</td></tr><tr><td><code>furlpay_positions</code></td><td>—</td><td><code>userAddress</code></td><td>Clearinghouse positions</td><td>LIVE (read)</td></tr><tr><td><code>furlpay_open_orders</code></td><td>—</td><td><code>userAddress</code></td><td>Resting orders</td><td>LIVE (read)</td></tr><tr><td><code>furlpay_portfolio_risk</code></td><td>—</td><td>—</td><td>Margin ratio / account risk evaluation</td><td>LIVE (read)</td></tr><tr><td><code>furlpay_preview_trade</code></td><td><code>symbol</code>, <code>side</code>, <code>size</code></td><td><code>leverage</code>, <code>price</code></td><td>Pre-trade risk evaluation of a hypothetical order — executes nothing</td><td>LIVE (evaluation)</td></tr><tr><td><code>furlpay_get_rwa_assets</code></td><td>—</td><td>—</td><td>Tokenized securities catalog; SEP-8 status is never claimed</td><td>LOCAL registry</td></tr><tr><td><code>furlpay_get_rwa_quote</code></td><td><code>asset</code>, <code>amount</code></td><td>—</td><td>Indicative RWA quote</td><td>SIMULATED</td></tr><tr><td><code>furlpay_finance_overview</code></td><td>—</td><td>—</td><td>Read-only finance layer overview (accounts, spend limits, settlement capabilities)</td><td>LOCAL ledger</td></tr><tr><td><code>furlpay_finance_ledger</code></td><td>—</td><td><code>reconcile</code>, <code>limit</code></td><td>Ledger view or full reconciliation report (balanced count, chain integrity)</td><td>LOCAL ledger</td></tr><tr><td><code>furlpay_finance_spend</code></td><td>—</td><td><code>unit</code></td><td>Spend report: window usage against limits</td><td>LOCAL ledger</td></tr><tr><td><code>furlpay_finance_treasury</code></td><td>—</td><td>—</td><td>Treasury balances (available vs reserved), inflow/outflow</td><td>LOCAL ledger</td></tr><tr><td><code>furlpay_finance_billing</code></td><td>—</td><td><code>sinceIso</code></td><td>Billing summary; fees reported separately from volume</td><td>LOCAL ledger</td></tr><tr><td><code>furlpay_finance_payments</code></td><td>—</td><td><code>limit</code>, <code>inspect</code></td><td>Payment history; states are the ledger&#39;s own (submission ≠ settlement)</td><td>LOCAL ledger</td></tr><tr><td><code>furlpay_oracle_price</code></td><td><code>asset</code></td><td>—</td><td>Multi-source USD quote (Coinbase/Kraken/Binance/Jupiter), median + cross-source agreement gate. <strong>DISAGREEMENT/UNAVAILABLE carry a null price</strong></td><td>LIVE (read-only)</td></tr><tr><td><code>furlpay_solana_cluster_status</code></td><td>—</td><td>—</td><td>Live Solana RPC reads (epoch/slot/block height). No signing path exists</td><td>LIVE (read-only)</td></tr><tr><td><code>furlpay_preview_execution</code></td><td><code>tool</code>, <code>args</code></td><td>—</td><td>Two-phase step 1: bind args to a one-time hash, show net effect</td><td>GATE (executes nothing)</td></tr></tbody></table><h3 id="hidden-by-default-—-execution-mode-policy-two-phase-required" tabindex="-1">Hidden by default — execution mode + policy + two-phase required <a class="header-anchor" href="#hidden-by-default-—-execution-mode-policy-two-phase-required" aria-label="Permalink to &quot;Hidden by default — execution mode + policy + two-phase required&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Required</th><th>Optional</th><th>What it does</th><th>Status</th></tr></thead><tbody><tr><td><code>furlpay_settle_invoice</code></td><td><code>challengeHeader</code></td><td><code>maxCost</code></td><td>Settle an x402 HTTP 402 challenge behind agent-policy checks (OFAC/SDN, velocity, spend caps). Policy gate records the spend atomically</td><td>SIMULATED (<code>SIMULATED</code> / <code>LOCAL_SIMULATION</code> labels)</td></tr><tr><td><code>furlpay_sweep_treasury</code></td><td><code>amountUsd</code></td><td><code>target</code> (<code>HLP</code> default / <code>FOBXX</code>)</td><td>Idle-USDC sweep. HLP: real signed vault transfer (policy-gated). FOBXX: labeled simulated. A missing <code>amountUsd</code> is refused, never defaulted</td><td>LIVE (HLP) / SIMULATED (FOBXX)</td></tr><tr><td><code>furlpay_trade</code></td><td><code>side</code>, <code>asset</code>, <code>amount</code>, <code>price</code></td><td><code>sponsor</code></td><td>Stellar limit orders with delegated budget enforcement</td><td>SIMULATED</td></tr><tr><td><code>furlpay_trade_perp</code></td><td><code>symbol</code>, <code>side</code>, <code>size</code>, <code>leverage</code></td><td><code>price</code></td><td>Hyperliquid L1 perpetual order (EIP-712 signed), risk engine enforced</td><td>LIVE (signed)</td></tr><tr><td><code>furlpay_execute_trade</code></td><td><code>symbol</code>, <code>side</code>, <code>size</code></td><td><code>leverage</code>, <code>price</code>, <code>orderType</code></td><td>Execute a perp order</td><td>LIVE (signed)</td></tr><tr><td><code>furlpay_cancel_order</code></td><td><code>symbol</code>, <code>orderId</code></td><td>—</td><td>Cancel a resting perp order</td><td>LIVE (signed)</td></tr><tr><td><code>furlpay_emergency_stop</code></td><td>—</td><td><code>symbol</code></td><td>Kill-switch; symbol-scoped when given (M-05 fix)</td><td>LIVE (signed)</td></tr><tr><td><code>furlpay_pay</code></td><td><code>recipient</code>, <code>amount</code></td><td><code>token</code>, <code>mandate</code></td><td>Platform A2A payment</td><td>Hosted API</td></tr><tr><td><code>furlpay_confirm_execution</code></td><td><code>executionHash</code></td><td>—</td><td>Two-phase step 2: execute the previewed call exactly once</td><td>GATE</td></tr></tbody></table><hr><h2 id="javascript-research-server-—-29-tools" tabindex="-1">JavaScript research server — 29 tools <a class="header-anchor" href="#javascript-research-server-—-29-tools" aria-label="Permalink to &quot;JavaScript research server — 29 tools&quot;">​</a></h2><p>Registered in <code>lib/mcp.js</code>; served by plain <code>furlpay mcp</code>. Same read-only default: its value-moving tools are hidden from <code>tools/list</code> without the startup policy gate passing.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Category</th><th>Status</th></tr></thead><tbody><tr><td><code>fork_list_networks</code></td><td>Fork assets (read-only)</td><td>IMPLEMENTED</td></tr><tr><td><code>fork_inspect_network</code></td><td>Fork assets (read-only)</td><td>IMPLEMENTED</td></tr><tr><td><code>fork_replay_check</code></td><td>Fork assets (read-only)</td><td>IMPLEMENTED</td></tr><tr><td><code>microstructure_analytics</code></td><td>Quant research (read-only)</td><td>IMPLEMENTED (offline)</td></tr><tr><td><code>microstructure_vpin</code></td><td>Quant research (read-only)</td><td>IMPLEMENTED (offline)</td></tr><tr><td><code>microstructure_quotes</code></td><td>Quant research (read-only)</td><td>IMPLEMENTED (offline)</td></tr><tr><td><code>algo_glft_quotes</code></td><td>Quant engines (read-only)</td><td>IMPLEMENTED (offline)</td></tr><tr><td><code>algo_breakeven</code></td><td>Quant engines (read-only)</td><td>IMPLEMENTED (offline)</td></tr><tr><td><code>algo_cascade</code></td><td>Quant engines (read-only)</td><td>IMPLEMENTED (offline)</td></tr><tr><td><code>chain_status</code></td><td>Platform view</td><td>Hosted API</td></tr><tr><td><code>get_balance</code> / <code>get_portfolio</code> / <code>get_net_worth</code></td><td>Platform view</td><td>Hosted API</td></tr><tr><td><code>get_quote</code> / <code>swap_tokens</code> / <code>send_stablecoin</code></td><td>Payments (mutating ones gated)</td><td>Hosted API</td></tr><tr><td><code>place_order</code> / <code>earn_deposit</code> / <code>earn_withdraw</code> / <code>furlpay_pay</code> / <code>set_card_controls</code> / <code>book_travel</code></td><td>Mutating — hidden by default</td><td>Hosted API</td></tr><tr><td><code>list_cards</code> / <code>list_transactions</code> / <code>list_trips</code> / <code>search_travel</code> / <code>earn_overview</code> / <code>market_movers</code></td><td>Read views</td><td>Hosted API</td></tr></tbody></table><p>Mutating tools on this surface (<code>send_stablecoin</code>, <code>earn_withdraw</code>, <code>place_order</code>, <code>swap_tokens</code>, <code>earn_deposit</code>, <code>book_travel</code>, <code>set_card_controls</code>, <code>furlpay_pay</code>) carry honest annotations and are structurally filtered in read-only mode exactly like the TS server.</p><hr><h2 id="client-configuration" tabindex="-1">Client configuration <a class="header-anchor" href="#client-configuration" aria-label="Permalink to &quot;Client configuration&quot;">​</a></h2><p>Claude Desktop / Cursor (<code>claude_desktop_config.json</code>):</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;furlpay-execution&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;furlpay&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--wallet&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;agent-alpha&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Read-only-only setups (research assistants, CI inspection) simply omit the wallet: plain <code>furlpay mcp</code> or <code>furlpay mcp --wallet &lt;name&gt;</code> without <code>--enable-execution</code> can quote, inspect and analyze, but never transact.</p><p><strong>Agent rules (load-bearing):</strong></p><ul><li>Read-only by default; never assume execution permissions exist.</li><li>Never invent payment completion — a preview is not a settlement, a <code>SIMULATED</code> label is not a transaction.</li><li>Never bypass Agent Trust: the policy gate runs before signing, on stored amounts, under an OS file lock.</li><li>Never expose credentials; keys arrive via environment/stdin, never argv.</li><li>Never retry a value-moving operation without respecting idempotency and the transaction status the ledger reports.</li></ul>`,26)])])}const y=t(r,[["render",s]]);export{h as __pageData,y as default};
